import{_ as t,o,c as a,a2 as r}from"./chunks/framework.CNDaxUod.js";const p=JSON.parse('{"title":"User guide","description":"","frontmatter":{},"headers":[],"relativePath":"guide/user-guide.md","filePath":"guide/user-guide.md"}'),s={name:"guide/user-guide.md"};function n(d,e,i,l,u,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="user-guide" tabindex="-1">User guide <a class="header-anchor" href="#user-guide" aria-label="Permalink to &quot;User guide&quot;">​</a></h1><p>For everyone on a standup roster. Total daily effort: about a minute. Share this page with your team.</p><h2 id="your-daily-flow" tabindex="-1">Your daily flow <a class="header-anchor" href="#your-daily-flow" aria-label="Permalink to &quot;Your daily flow&quot;">​</a></h2><p>At the standup&#39;s prompt time, in <strong>your</strong> timezone, AsyncUp sends you a card in a Google Chat DM.</p><ol><li>Press <strong>Fill standup</strong>. One form, all the questions, one submit. Every question and the mood are required: if one is empty, the form comes back with a red line naming it and your answers kept. Answer the blockers question with &quot;none&quot; when there are none. After the mood there&#39;s an optional <strong>Want to say why?</strong> box, up to 200 characters. Only people allowed to read mood comments see it, and it is never posted in the space.</li><li>Your answers post as your card under today&#39;s thread in the team space. Your mood never appears there: it&#39;s seen in the web app only. &quot;Yesterday&quot; comes pre-filled from your previous &quot;today&quot;.</li><li>Plans changed? Your DM card now shows <em>Submitted at …</em> with <strong>Edit answers</strong> until the deadline. Editing updates the posted card in place, marked <em>edited</em>. After the deadline a first submission still posts, marked <em>late</em>.</li><li>Not today? Press <strong>🏖️ Skip today</strong> and say why in one line. The reason goes in today&#39;s thread, and you&#39;re listed as away, never as missing. Changed your mind? <strong>↩️ Undo skip</strong> (or DM <code>unskip</code>) before the deadline removes that reply and brings the form back.</li></ol><p>Reminders and nudges update the same way as the prompt card.</p><h2 id="blockers" tabindex="-1">Blockers <a class="header-anchor" href="#blockers" aria-label="Permalink to &quot;Blockers&quot;">​</a></h2><p>Any blockers answer other than &quot;none&quot; opens a blocker. The bot DMs you its card: <strong>👥 Tag people</strong> pulls in anyone in your Workspace who can help, <strong>📝 Add update</strong> keeps everyone involved posted, <strong>✅ Resolve</strong> closes it.</p><p>When someone tags you on a blocker you get the same card. <strong>✋ Acknowledge</strong> tells the reporter you&#39;re on it and stops the daily nudges.</p><p>Untagged blockers resolve themselves the next time you answer &quot;none&quot;. Once a blocker is tagged or has updates, only an explicit resolve closes it.</p><h2 id="dm-the-bot" tabindex="-1">DM the bot <a class="header-anchor" href="#dm-the-bot" aria-label="Permalink to &quot;DM the bot&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Effect</th></tr></thead><tbody><tr><td><code>vacation</code> (or <code>ooo</code>)</td><td>Pause prompts across all your standups</td></tr><tr><td><code>back</code></td><td>Resume prompts</td></tr><tr><td><code>unskip</code></td><td>Take back today&#39;s skip while the run is open</td></tr><tr><td><code>timezone Asia/Kolkata</code></td><td>Get prompts at the standup&#39;s time in <em>your</em> zone</td></tr><tr><td><code>timezone</code> / <code>timezone reset</code></td><td>Show / clear your personal timezone</td></tr><tr><td><code>off tomorrow comp off</code> / <code>off 22 sep to 24 sep sick</code> / <code>working sat</code></td><td>A day (or range) off, or an extra working day — see <a href="./schedules.html">Personal schedules</a></td></tr><tr><td><code>off list</code> / <code>off cancel &lt;date&gt;</code></td><td>What&#39;s coming up / withdraw an entry</td></tr><tr><td><code>days mon-thu</code> / <code>days adhoc</code> / <code>days reset</code></td><td>Your own week, or back to the standup&#39;s</td></tr></tbody></table><h2 id="your-own-page-—-app-me" tabindex="-1">Your own page — <code>/app/me</code> <a class="header-anchor" href="#your-own-page-—-app-me" aria-label="Permalink to &quot;Your own page — `/app/me`&quot;">​</a></h2><p>Sign in at <code>https://HOST/app</code> with <strong>Continue with Google</strong> or <strong>Continue with SSO</strong>. You get:</p><ul><li>today&#39;s standups with an <strong>Answer in Chat</strong> link and <strong>Skip today</strong> (it asks for the one-line reason too);</li><li>your recent answers;</li><li>your timezone, vacation mode and <strong>My schedule</strong> (your week and days off).</li></ul><p>If your account isn&#39;t linked to Chat yet, it links the first time you use the bot, or straight away when your admins have set up the <a href="./directory.html">Directory</a>.</p><h2 id="polls" tabindex="-1">Polls <a class="header-anchor" href="#polls" aria-label="Permalink to &quot;Polls&quot;">​</a></h2><p>Anyone can start one in a space: <code>@AsyncUp poll Ship Friday? | Yes | No</code>. Tap an option to vote; tap another to change your vote.</p>',18)])])}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
